mapper.select:
select distinct MONTH_PLAN_VERSION
from T_MP_PROC_VERSION
where IFNULL(IS_DELETE, 0) = 0
  and YEAR = #{year}
  and MONTH = #{month}
  and FACTORY_CODE = #{factoryCode}
  and MONTH_PLAN_VERSION is not null

SELECT COUNT(DISTINCT PRODUCT_CODE) AS skuCount,
       SUM(PLAN_QTY)                AS skuQty,
       SUM(ALLOCATION_QTY)          AS stockHedgingQty,
       SUM(PRODUCE_QTY_DUE)         AS gapQty
FROM T_MP_ORDER_PLAN_ALLOCATION
WHERE IS_DELETE = 0
  AND `YEAR` = #{year}
  AND `MONTH` = #{month}
  AND FACTORY_CODE = #{factoryCode}
  AND MONTH_PLAN_VERSION = #{monthPlanVersion}
AND PRODUCT_CODE = #{productCode}
AND PRODUCT_DESC = #{productDesc}
AND LOCATION_TYPE = #{locationType}
AND CHANNEL = #{channel}
AND BRAND = #{brand}
AND PRO_SIZE = #{proSize}
AND SPECIFICATIONS = #{specifications}
AND PATTERN = #{pattern}

SELECT
SUM(a.DOMESTIC_STOCK_QTY)
SUM(a.FOREIGN_STOCK_QTY)
SUM(a.OE_STOCK_QTY)
SUM(a.STOCK_QTY)
FROM t_mp_month_require_stock a
WHERE a.IS_DELETE = 0
AND a.`YEAR` = #{year}
AND a.`MONTH` = #{month}
AND a.MONTH_PLAN_VERSION = #{monthPlanVersion}
AND a.PRODUCT_CODE = #{productCode}
AND a.PRODUCT_DESC = #{productDesc}
AND a.BRAND = #{brand}
AND a.PRO_SIZE = #{proSize}
AND a.SPECIFICATIONS = #{specifications}
AND a.PATTERN = #{pattern}
